source.patch:
From ad50d81027f7e7716f2b9ab28b7aa476eae2d741 Mon Sep 17 00:00:00 2001
From: Dan Bloomberg <dan.bloomberg@gmail.com>
Date: Mon, 30 Mar 2020 11:23:02 -0700
Subject: [PATCH] A multiple free fuzzer crash with ojpeg. * Check earlier for
 invalid ojpeg file.

---
 src/tiffio.c | 12 +++++-------
 1 file changed, 5 insertions(+), 7 deletions(-)

diff --git a/src/tiffio.c b/src/tiffio.c
index 82975a5..8bd92b2 100644
--- a/src/tiffio.c
+++ b/src/tiffio.c
@@ -548,6 +548,11 @@ PIXCMAP   *cmap;
         return NULL;
     }

+    TIFFGetFieldDefaulted(tif, TIFFTAG_COMPRESSION, &tiffcomp);
+    if (tiffcomp == COMPRESSION_OJPEG && d != 8) {
+        return (PIX *)ERROR_PTR("invalid ojpeg file", procName, NULL);
+    }
+
     if ((pix = pixCreate(w, h, d)) == NULL)
         return (PIX *)ERROR_PTR("pix not made", procName, NULL);
     pixSetInputFormat(pix, IFF_TIFF);
@@ -555,8 +560,6 @@ PIXCMAP   *cmap;
     wpl = pixGetWpl(pix);
     bpl = 4 * wpl;

-    TIFFGetFieldDefaulted(tif, TIFFTAG_COMPRESSION, &tiffcomp);
-
         /* Thanks to Jeff Breidenbach, we now support reading 8 bpp
          * images encoded in the long-deprecated old jpeg format,
          * COMPRESSION_OJPEG.  TIFFReadScanline() fails on this format,
@@ -618,11 +621,6 @@ PIXCMAP   *cmap;
         }

         if (spp == 1) {  /* 8 bpp, old jpeg format */
-            if (pixGetDepth(pix) != 8) {
-                LEPT_FREE(tiffdata);
-                pixDestroy(&pix);
-                return (PIX *)ERROR_PTR("invalid ojpeg file", procName, NULL);
-            }
             pixdata = pixGetData(pix);
             for (i = 0; i < h; i++) {
                 line = pixdata + i * wpl;
-- 
